cat << 'EOF' > /app/ars.R
# Adaptive Rejection Sampling (ARS) Implementation in R
# Based on Gilks & Wild (1992)

log_density_grad <- function(density_func, x, h_eps = 1e-5) {
  vals <- density_func(x)
  if (any(!is.finite(vals)) || any(vals <= 0)) {
    stop("Density function must return positive finite values within domain.")
  }
  h <- log(vals)
  h_plus <- log(density_func(x + h_eps))
  h_minus <- log(density_func(x - h_eps))
  dh <- (h_plus - h_minus) / (2 * h_eps)
  list(h = h, dh = dh)
}

ars_init <- function(density_func, domain, x_init = NULL) {
  if (is.null(x_init)) {
    if (is.infinite(domain[1]) && is.infinite(domain[2])) {
      x_init <- c(-1, 0, 1)
    } else if (is.infinite(domain[1])) {
      x_init <- c(domain[2] - 2, domain[2] - 1, domain[2] - 0.5)
    } else if (is.infinite(domain[2])) {
      x_init <- c(domain[1] + 0.5, domain[1] + 1, domain[1] + 2)
    } else {
      x_init <- seq(domain[1], domain[2], length.out = 4)[2:3]
    }
  }
  x_init <- sort(unique(x_init))
  x_init <- x_init[x_init >= domain[1] & x_init <= domain[2]]
  if (length(x_init) < 2) {
    stop("Initialization requires at least 2 valid points within domain.")
  }
  evals <- lapply(x_init, function(x) log_density_grad(density_func, x))
  h <- sapply(evals, function(e) e$h)
  dh <- sapply(evals, function(e) e$dh)
  for (i in 1:(length(x_init) - 1)) {
    if (dh[i] < dh[i+1] - 1e-3) {
      stop(paste0("Non-log-concavity detected during initialization at x = ", x_init[i]))
    }
  }
  list(x = x_init, h = h, dh = dh, domain = domain)
}

get_upper_hull_z <- function(hull) {
  x <- hull$x
  h <- hull$h
  dh <- hull$dh
  K <- length(x)
  z <- numeric(K + 1)
  z[1] <- hull$domain[1]
  z[K + 1] <- hull$domain[2]
  if (K > 1) {
    for (i in 1:(K - 1)) {
      denom <- dh[i] - dh[i+1]
      if (abs(denom) < 1e-12) {
        z[i+1] <- (x[i] + x[i+1]) / 2
      } else {
        z_val <- (h[i+1] - h[i] - x[i+1]*dh[i+1] + x[i]*dh[i]) / denom
        if (z_val <= x[i] || z_val >= x[i+1]) {
          z_val <- (x[i] + x[i+1]) / 2
        }
        z[i+1] <- z_val
      }
    }
    for (i in 2:K) {
      if (z[i] <= z[i-1]) {
        z[i] <- (x[i-1] + x[i]) / 2
      }
    }
  }
  z
}

ars <- function(density_function, domain, n = 1000) {
  if (!is.function(density_function)) stop("density_function must be a function.")
  if (!is.numeric(domain) || length(domain) != 2 || domain[1] >= domain[2]) stop("Invalid domain.")
  if (!is.numeric(n) || length(n) != 1 || n <= 0 || n != round(n)) stop("Invalid n.")

  hull <- ars_init(density_function, domain)
  samples <- numeric(n)
  accepted <- 0
  max_iters <- n * 50
  iters <- 0

  while (accepted < n && iters < max_iters) {
    iters <- iters + 1
    z <- get_upper_hull_z(hull)
    x <- hull$x
    h <- hull$h
    dh <- hull$dh
    K <- length(x)

    log_weights <- numeric(K)
    for (i in 1:K) {
      zi <- z[i]
      zi1 <- z[i+1]
      dhi <- dh[i]
      hi <- h[i]
      xi <- x[i]
      if (abs(dhi) < 1e-10) {
        log_weights[i] <- hi - dhi*xi + log(zi1 - zi)
      } else {
        term1 <- dhi * (zi1 - xi)
        term2 <- dhi * (zi - xi)
        if (dhi > 0) {
          log_w <- hi - dhi*xi + term1 + log(1 - exp(term2 - term1))
        } else {
          log_w <- hi - dhi*xi + term2 + log(exp(term1 - term2) - 1)
        }
        log_weights[i] <- log_w
      }
    }

    max_lw <- max(log_weights)
    weights <- exp(log_weights - max_lw)
    probs <- weights / sum(weights)

    interval_idx <- sample(K, 1, prob = probs)
    zi <- z[interval_idx]
    zi1 <- z[interval_idx+1]
    dhi <- dh[interval_idx]
    xi <- x[interval_idx]

    u_rand <- runif(1)
    if (abs(dhi) < 1e-10) {
      x_star <- zi + u_rand * (zi1 - zi)
    } else {
      term_low <- dhi * (zi - xi)
      term_high <- dhi * (zi1 - xi)
      if (dhi > 0) {
        arg <- exp(term_low) + u_rand * (exp(term_high) - exp(term_low))
        if (arg <= 0) arg <- 1e-12
        x_star <- xi + log(arg) / dhi
      } else {
        arg <- exp(term_low) - u_rand * (exp(term_low) - exp(term_high))
        if (arg <= 0) arg <- 1e-12
        x_star <- xi + log(arg) / dhi
      }
    }

    x_star <- max(zi, min(zi1, x_star))
    eval_star <- tryCatch(log_density_grad(density_function, x_star), error = function(e) NULL)
    if (is.null(eval_star)) next

    h_star <- eval_star$h
    dh_star <- eval_star$dh
    u_star <- h[interval_idx] + dh[interval_idx] * (x_star - x[interval_idx])

    u_rand2 <- runif(1)
    if (log(u_rand2) <= h_star - u_star) {
      accepted <- accepted + 1
      samples[accepted] <- x_star
    }

    new_x <- sort(c(x, x_star))
    new_evals <- lapply(new_x, function(xx) {
      if (xx == x_star) list(h = h_star, dh = dh_star)
      else {
        idx <- which(x == xx)
        list(h = h[idx], dh = dh[idx])
      }
    })
    new_dh <- sapply(new_evals, function(e) e$dh)

    log_concave_ok <- TRUE
    for (i in 1:(length(new_x) - 1)) {
      if (new_dh[i] < new_dh[i+1] - 1e-2) {
        log_concave_ok <- FALSE
        break
      }
    }

    if (!log_concave_ok) {
      stop(paste0("Non-log-concave density detected at x = ", x_star))
    }

    hull$x <- new_x
    hull$h <- sapply(new_evals, function(e) e$h)
    hull$dh <- sapply(new_evals, function(e) e$dh)
  }

  if (accepted < n) {
    warning("Reached max iterations.")
    samples <- samples[1:accepted]
  }
  samples
}

test <- function() {
